<template><el-card><template #header>Approval details</template><el-descriptions v-if="item"><el-descriptions-item label="Record">{{item.record_id}}</el-descriptions-item><el-descriptions-item label="Status">{{item.status}}</el-descriptions-item></el-descriptions><el-table :data="item?.changes||[]"><el-table-column prop="field_name" label="Field"/><el-table-column prop="old_value" label="Old"/><el-table-column prop="new_value" label="New"/></el-table><el-button v-if="item?.status==='PENDING'" type="primary" @click="doApprove">Approve</el-button></el-card></template>
<script setup>import{ref,onMounted}from'vue';import{useRoute}from'vue-router';import{getApproval,approve}from'../../api/workflow';const route=useRoute(),item=ref(null);async function load(){item.value=(await getApproval(route.params.id)).data}async function doApprove(){await approve(route.params.id);await load()}onMounted(load)</script>